pub struct ZeroCopyTokenizer<'a> {
    remainder: &'a str,
    delimiters: &'a [char],
}

impl<'a> ZeroCopyTokenizer<'a> {
    pub fn new(input: &'a str, delimiters: &'a [char]) -> Self {
        Self { remainder: input, delimiters }
    }
}

impl<'a> Iterator for ZeroCopyTokenizer<'a> {
    type Item = &'a str;
    fn next(&mut self) -> Option<Self::Item> {
        if self.remainder.is_empty() {
            return None;
        }
        match self.remainder.find(|c: char| self.delimiters.contains(&c)) {
            Some(idx) => {
                let token = &self.remainder[..idx];
                self.remainder = &self.remainder[idx + 1..];
                Some(token)
            }
            None => {
                let token = self.remainder;
                self.remainder = "";
                Some(token)
            }
        }
    }
}

