#[cfg(test)]
mod tests {
    use super::*;
    #[test]
    fn test_zero_copy_tokens() {
        let delims = [',', ';'];
        let text = "foo,bar;baz";
        let mut tok = ZeroCopyTokenizer::new(text, &delims);
        assert_eq!(tok.next(), Some("foo"));
        assert_eq!(tok.next(), Some("bar"));
        assert_eq!(tok.next(), Some("baz"));
        assert_eq!(tok.next(), None);
    }
}
